        assert_eq!(rotate_right(&v, 1), vec![5, 1, 2, 3, 4]);
        assert_eq!(rotate_right(&v, 2), vec![4, 5, 1, 2, 3]);
        assert_eq!(rotate_right(&v, 5), vec![1, 2, 3, 4, 5]); // mod len
        assert_eq!(rotate_right(&v, 7), vec![4, 5, 1, 2, 3]); // 7 % 5 == 2
